"""Escaped, saved invoice HTML. No live CRM lookups or payment assumptions."""
from quote_print import h,money,amount,lines_text,details
from invoice_rules import validate_invoice_document
STYLE='*{box-sizing:border-box}body{font:14px Arial,sans-serif;color:#20252a;margin:0;background:#f5f6fa}.sheet{max-width:1000px;margin:24px auto;padding:40px;background:white}h1{font-size:30px;color:#b72030;margin:0 0 10px}h2{overflow-wrap:anywhere;font-size:19px;margin:0 0 10px}.heading,.parties{display:flex;justify-content:space-between;gap:24px}.heading>div,.parties>div{flex:1;min-width:0;overflow-wrap:anywhere}.right{text-align:right}.parties{margin:30px 0}.label{color:#656b73;font-size:12px;font-weight:bold;text-transform:uppercase;margin-bottom:8px}p{line-height:1.5}table{width:100%;table-layout:fixed;font-size:12px;border-collapse:collapse;margin:25px 0}thead{display:table-header-group}th{background:#f2f3f5;text-align:left;font-size:12px}td,th{padding:10px 5px;border-bottom:1px solid #ddd;vertical-align:top;overflow-wrap:anywhere}.num{text-align:right;white-space:normal;font-variant-numeric:tabular-nums}.muted{color:#666;font-size:12px;margin-top:7px}.totals{margin-left:auto;width:310px}.totals>div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eee}.totals>div:last-child{font-size:20px;color:#b72030}.terms{margin-top:28px;border-top:1px solid #ddd;padding-top:18px;overflow-wrap:anywhere}.draft{padding:12px;background:#fff1cf;font-weight:bold}.print-help{max-width:1000px;margin:18px auto;padding:0 15px}.footer{margin-top:30px;font-size:12px;color:#666}tr{break-inside:avoid}@page{size:letter;margin:14mm}@media print{body{background:white;font-size:12px}h1{font-size:26px}h2{font-size:17px}p{margin:8px 0;line-height:1.4}.parties{margin:18px 0}table{margin:18px 0}td,th{padding:8px 5px}.totals>div{padding:6px}.terms{margin-top:18px;padding-top:10px}.footer{margin-top:18px}.draft{padding:8px}.sheet{margin:0;padding:0;max-width:none}.print-help{display:none}a{color:inherit;text-decoration:none}.heading,.parties,.totals{break-inside:avoid}}@media(max-width:650px){.sheet{padding:20px}.heading,.parties{display:block}.right{text-align:left}.scroll{overflow-x:auto}}\n'

STYLE+=' .page-stamp{display:none}@media print{.page-stamp{display:block;position:fixed;bottom:-9mm;left:0;right:0;text-align:center;font-size:9px;color:#a61d2d}}'

def render_invoice(r):
    validate_invoice_document(r);q=r['quote_snapshot'];d=q['data'];m=r['details'];seller=q['seller_snapshot']
    buyer={**q['customer_snapshot'],'address':m['billing_address'],'tax_id':m['billing_tax_id']};contact=q.get('contact_snapshot') or {}
    title='VAT INVOICE' if m['document_type']=='vat_invoice' else 'VAT SALES RECEIPT'
    banner='TEST — NOT A COMMERCIAL OR TAX DOCUMENT' if r['is_test'] else 'DRAFT — NOT ISSUED' if r['status']=='draft' else ''
    rows=[]
    for l,c in zip(d['lines'],m['tax_codes']):
        extra=' · '.join(x for x in (l['finish'],l['placement']) if x)
        rows.append('<tr><td>'+lines_text(l['description'])+('<div class="muted">'+h(extra)+'</div>' if extra else '')+'</td><td class="num">'+h(l['quantity'])+' '+h(l['unit'])+'</td><td class="num">'+h(l['unit_price'])+'</td><td class="num">'+h(l['discount_percent'])+'%<br>'+amount(l['discount_cents'])+'</td><td class="num">'+amount(l['net_cents'])+'</td><td class="num">'+h(c or '?')+' · '+h(l['vat_rate'])+'%<br>'+amount(l['tax_cents'])+'</td></tr>')
    sums=''.join('<div><span>'+name+'</span><strong>'+money(value)+'</strong></div>' for name,value in [('Subtotal',d['subtotal_cents']),('Discount',d['discount_cents']),('Net before VAT',d['subtotal_cents']-d['discount_cents']),('VAT',d['tax_cents']),('Invoice total',d['total_cents'])])
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+h(r['number'])+'</title><style>'+STYLE+'</style></head><body><p class="print-help">Use your browser’s Print command to print or save as PDF. <a href="/invoices">Back to invoices</a></p>'+('<div class="page-stamp">'+h(r['number'])+(' · '+banner if banner else '')+'</div>')+'<main class="sheet">'+('<p class="draft">'+banner+'</p>' if banner else '')+\
    '<div class="heading"><div><h1>'+h(seller['name'])+'</h1><p>'+details(seller,['address','email','phone','website'])+'</p><p>VAT ID: '+h(seller['tax_id'])+'</p></div><div class="right"><h2>'+title+'</h2><h2>'+h(r['number'])+'</h2><p>Invoice date: '+h(m['invoice_date'])+'<br>Payment due: '+h(m['due_date'])+('<br>Earlier supply/payment: '+h(m['supply_date']) if m['supply_date'] else '')+'<br>Revision: '+h(r['version'])+'</p><p>Source quote: '+h(q['number'])+'<br>Currency: BSD · Unit prices before VAT</p></div></div>'+\
    '<div class="parties"><div><div class="label">Billed to</div><strong>'+h(buyer['name'])+'</strong><p>'+details(buyer,['address','email','phone'])+'</p>'+('<p>Customer VAT ID: '+h(buyer['tax_id'])+'</p>' if buyer.get('tax_id') else '')+'</div><div><div class="label">Contact</div><p>'+details(contact,['name','title','email','phone'])+'</p></div></div><h2>'+h(d['title'])+'</h2>'+\
    '<div class="scroll"><table><colgroup><col style="width:30%"><col style="width:12%"><col style="width:14%"><col style="width:12%"><col style="width:16%"><col style="width:16%"></colgroup><thead><tr><th>Description</th><th class="num">Quantity</th><th class="num">Unit price<br>BSD</th><th class="num">Discount<br>% / BSD</th><th class="num">Net excl. VAT<br>BSD</th><th class="num">VAT<br>% / BSD</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><p class="muted">T: taxable · Z: zero-rated · E: exempt.'+(' ? means classification is pending in this draft.' if '' in m['tax_codes'] else '')+'</p>'+\
    '<section class="totals">'+sums+'</section><p class="right">Quoted deposit requirement ('+h(d['deposit_percent'])+'%): '+money(d['deposit_cents'])+'</p>'+\
    ('<section class="terms"><div class="label">Notes</div><p>'+lines_text(m['notes'])+'</p></section>' if m['notes'] else '')+'<section class="terms"><div class="label">Terms</div><p>'+lines_text(m['terms'])+'</p></section><p class="footer">'+('Test document only. No amount is payable.' if r['is_test'] else 'Draft for review. Not an issued invoice.' if r['status']=='draft' else 'This document states the invoice total. Payments received are acknowledged separately.')+'</p></main></body></html>'
